class Solution:
    def canReach(self, s: str, minJump: int, maxJump: int) -> bool:
		# dp[i] represents whether i is reachable
        dp = [False for _ in s]
        dp[0] = True

        for i in range(1, len(s)):
            if s[i] == "1":
                continue

			# iterate through the solutions in range [i - maxJump, i - minJump]
			# and if any previous spot in range is reachable, then i is also reachable
            window_start = max(0, i - maxJump)
            window_end = i - minJump
            for j in range(window_start, window_end + 1):
                if dp[j]:
                    dp[i] = True
                    break

        return dp[-1]

class Solution:
    def minFlips(self, s: str) -> int:
        prev = 0
        start_1, start_0, start_1_odd, start_0_odd = 0,0,sys.maxsize,sys.maxsize
        odd = len(s)%2
        for val in s:
            val = int(val)
            if val == prev:
                if odd:
                    start_0_odd = min(start_0_odd, start_1)
                    start_1_odd += 1
                start_1 += 1
            else:
                if odd:
                    start_1_odd = min(start_1_odd, start_0)
                    start_0_odd += 1
                start_0 += 1
            prev = 1 - prev
        return min([start_1, start_0, start_1_odd, start_0_odd])

