class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        ans, empty = 0, 1

        def dfs(grid: List[List[int]], row: int, col: int, count: int, visited) -> None:
            if row >= len(grid) or col >= len(grid[0]) or row < 0 or col < 0 or grid[row][col] == -1:
                return
            nonlocal ans
            if grid[row][col] == 2:
                if empty == count:
                    ans += 1
                return
            if (row, col) not in visited:
                visited.add((row, col))
                dfs(grid, row + 1, col, count + 1, visited)
                dfs(grid, row - 1, col, count + 1, visited)
                dfs(grid, row, col + 1, count + 1, visited)
                dfs(grid, row, col - 1, count + 1, visited)
                visited.remove((row, col))

        row, col = 0, 0
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == 1:
                    row, col = i, j
                elif grid[i][j] == 0:
                    empty += 1
        dfs(grid, row, col, 0, set())
        return ans

class Solution:
    def tilingRectangle(self, n: int, m: int) -> int:
      # try brute force backtracking?
      board = [[0 for _ in range(n)] for _ in range(m)]

      ans = math.inf
      def bt(counts):
        nonlocal ans
        if counts >= ans:
          return

        pos = None
        found = False
        for row in range(m):
          for col in range(n):
            if board[row][col] == 0:
              pos = (row, col)
              found = True
              break
          if found:
            break
        if not found:
          ans = min(ans, counts)
          return

        # see how many difference size of squares we can place from this spot
        r, c = pos
        offset = 0
        while r + offset < m and c + offset < n and board[r + offset][c] == 0 and board[r][c + offset] == 0:
          offset += 1
        # max can place size is offset
        for row in range(r, r + offset):
          for col in range(c, c + offset):
            board[row][col] = 1
        # do bt and shrink
        while offset > 0:
          bt(counts + 1)
          # shrink
          for row in range(r, r + offset):
            board[row][c + offset - 1] = 0
          for col in range(c, c + offset):
            board[r + offset - 1][col] = 0
          offset -= 1

      bt(0)
      return ans

